with c as(select id from bm_categories where name='Liqueur') insert into bm_ingredients(name,category_id) select x,c.id from c cross join (values('Crème de Cassis'),('Allspice Dram'),('Triple Sec'),('Amaretto'),('Amaro')) v(x) on conflict do nothing;
with c as(select id from bm_categories where name='Spirit') insert into bm_ingredients(name,category_id) select x,c.id from c cross join (values('London Dry Gin'),('Mezcal'),('Bourbon'),('Blanco Tequila')) v(x) on conflict do nothing;
